def test_review_p0_gates(planned: Path, tmp_path: Path) -> None:
    from pitchdeck.revisions import (
        GovernanceUndoRefused,
        OutOfBandEdit,
        check_out_of_band,
        undo_last_write,
    )
    from pitchdeck.slide_edit import apply_slide_edit

    sources, ledger, assets = _base_models(tmp_path)

    # Fixture approval blocks publish, passes draft.
    fixture_claim = Claim(
        id="fx", text="Fixture-approved claim", kind=ClaimKind.PRODUCT,
        visibility=Visibility.PUBLIC, source_refs=[SourceRef(source_id="public-source")],
        risk=ClaimRisk.MEDIUM, status=ClaimStatus.APPROVED,
        approval=ClaimApproval(approved_by="fixture-maintainer", approved_at="2026-08-05", fixture=True),
    )
    ledger_fx = ledger.model_copy(update={"claims": [*ledger.claims, fixture_claim]})
    publish = _run(_deck(_slide(claim_ids=["fx"])), ledger_fx, sources, assets, tmp_path, publish=True)
    assert any(i.code == "APPROVAL_FIXTURE" and i.severity == "error" for i in publish.issues)
    draft = _run(_deck(_slide(claim_ids=["fx"])), ledger_fx, sources, assets, tmp_path)
    assert not any(i.code == "APPROVAL_FIXTURE" for i in draft.issues)

    # Mermaid %%{init}%% directive rejected.
    slide = _slide(visual=VisualSpec(type="mermaid", source="%%{init: {'securityLevel':'loose'}}%%\ngraph TD; A-->B"))
    report = _run(_deck(slide), ledger, sources, assets, tmp_path)
    assert any(i.code == "MERMAID_DIRECTIVE" and i.severity == "error" for i in report.issues)

    # DIAGRAM_NO_SNAPSHOT escalates to error at publish.
    slide2 = _slide(visual=VisualSpec(type="mermaid", source="graph TD; A-->B"))
    pub = _run(_deck(slide2), ledger, sources, assets, tmp_path, publish=True)
    assert any(i.code == "DIAGRAM_NO_SNAPSHOT" and i.severity == "error" for i in pub.issues)

    # Out-of-band edit detected before undo.
    sid = sorted(load_yaml(planned / "deck.public.yaml", DeckManifest).slides, key=lambda s: s.order)[1].id
    apply_slide_edit(planned, tmp_path / "ui", slide_id=sid, field="footer", value="v1")
    deck_file = planned / "deck.public.yaml"
    deck_file.write_text(deck_file.read_text().replace("v1", "hand-edited"))
    with pytest.raises(OutOfBandEdit):
        check_out_of_band(planned)
    with pytest.raises(OutOfBandEdit):
        undo_last_write(planned)

    # Governance file in archive refuses undo.
    gov_bundle = tmp_path / "gov"
    gov_bundle.mkdir()
    from pitchdeck.revisions import commit_bundle_write

    commit_bundle_write(gov_bundle, {gov_bundle / "claim_ledger.yaml": "schema: x\n"})
    commit_bundle_write(gov_bundle, {gov_bundle / "claim_ledger.yaml": "schema: y\n"})
    with pytest.raises(GovernanceUndoRefused):
        undo_last_write(gov_bundle)


def test_evidence_allowlist_scan(tmp_path: Path) -> None:
    from pitchdeck.artifact_scan import ArtifactLeak, scan_artifact

    sources, ledger, assets = _base_models(tmp_path)
    deck = _deck(_slide())
    good = tmp_path / "good.html"
    good.write_text('<section data-claims="[{&quot;id&quot;: &quot;public-claim&quot;, &quot;text&quot;: &quot;x&quot;, &quot;status&quot;: &quot;approved&quot;, &quot;qualifier&quot;: &quot;&quot;}]">T M</section>')
    # good.html lacks the slide strings; build minimal deck text into it
    good.write_text('<h1>T</h1><p>M</p><section data-claims="[{&quot;id&quot;: &quot;public-claim&quot;, &quot;text&quot;: &quot;x&quot;, &quot;status&quot;: &quot;approved&quot;, &quot;qualifier&quot;: &quot;&quot;}]"></section>')
    scan_artifact(good, deck, ledger, sources)  # passes: approved public record, allowlisted keys

    bad_keys = tmp_path / "bad-keys.html"
    bad_keys.write_text('<h1>T</h1><p>M</p><i data-claims="[{&quot;id&quot;: &quot;public-claim&quot;, &quot;text&quot;: &quot;x&quot;, &quot;status&quot;: &quot;approved&quot;, &quot;qualifier&quot;: &quot;&quot;, &quot;approved_by&quot;: &quot;alice@internal&quot;}]"></i>')
    with pytest.raises(ArtifactLeak, match="non-allowlisted"):
        scan_artifact(bad_keys, deck, ledger, sources)

    candidate = tmp_path / "candidate.html"
    candidate.write_text('<h1>T</h1><p>M</p><i data-claims="[{&quot;id&quot;: &quot;public-claim&quot;, &quot;text&quot;: &quot;x&quot;, &quot;status&quot;: &quot;candidate&quot;, &quot;qualifier&quot;: &quot;&quot;}]"></i>')
    with pytest.raises(ArtifactLeak, match="not approved"):
        scan_artifact(candidate, deck, ledger, sources)


def test_simulate_dry_run_real_pipeline(planned: Path) -> None:
    from pitchdeck.slide_edit import simulate_edit

    deck = load_yaml(planned / "deck.public.yaml", DeckManifest)
    sid = sorted(deck.slides, key=lambda s: s.order)[1].id
    before = (planned / "deck.public.yaml").read_text()

    # Passing mutation: diff returned, gate codes empty, NOTHING written.
    ok = simulate_edit(planned, slide_id=sid, field="footer", value="simulated footer")
    assert ok["would_pass"] and "simulated footer" in ok["diff"] and not ok["gate_codes"]
    assert (planned / "deck.public.yaml").read_text() == before

    # Failing mutation: forbidden phrase surfaces its gate code, still no writes.
    bad = simulate_edit(planned, slide_id=sid, field="footer", value="totally production-ready")
    assert not bad["would_pass"]
    assert "FORBIDDEN_UNQUALIFIED_CLAIM" in bad["gate_codes"]
    assert (planned / "deck.public.yaml").read_text() == before

    # Deck op simulation (delete) also dry-runs.
    op = simulate_edit(planned, slide_id=sid, op="delete")
    assert op["would_pass"] and (planned / "deck.public.yaml").read_text() == before


def test_span_first_rendering_gates(tmp_path: Path) -> None:
    from pitchdeck.models import EvidenceSpan

    sources, ledger, assets = _base_models(tmp_path)
    span = EvidenceSpan(source_id="public-source", text="The pipeline processed 1200 documents in 45 minutes.")
    claim = Claim(
        id="span-claim", text="The pipeline processed 1200 documents in 45 minutes.",
        kind=ClaimKind.PROOF, visibility=Visibility.PUBLIC,
        source_refs=[SourceRef(source_id="public-source")], risk=ClaimRisk.MEDIUM,
        status=ClaimStatus.APPROVED,
        approval=ClaimApproval(approved_by="h", approved_at="2026-08-06"),
        evidence_spans=[span],
    )
    ledger2 = ledger.model_copy(update={"claims": [*ledger.claims, claim]})

    def deck_with(message, transform, claim_id="span-claim"):
        slide = _slide(
            message=message,
            claim_ids=[claim_id],
            bindings=[
                TextBinding(path="title", kind=BindingKind.NON_CLAIM),
                TextBinding(path="message", kind=BindingKind.CLAIM_PARAPHRASE, claim_id=claim_id, transform_class=transform),
            ],
        )
        return _deck(slide)

    # Verbatim rendering passes; digit-flip trips NUMERIC_UNBOUND at publish.
    ok = _run(deck_with("The pipeline processed 1200 documents in 45 minutes.", "verbatim"), ledger2, sources, assets, tmp_path, publish=True)
    assert not any(i.code in {"NUMERIC_UNBOUND", "TRANSFORM_MISMATCH", "RENDERING_UNBOUND"} for i in ok.issues)
    flipped = _run(deck_with("The pipeline processed 1300 documents in 45 minutes.", None), ledger2, sources, assets, tmp_path, publish=True)
    assert any(i.code == "NUMERIC_UNBOUND" and i.severity == "error" for i in flipped.issues)

    # Claimed verbatim but actually rewritten -> TRANSFORM_MISMATCH.
    lied = _run(deck_with("Documents fly through at record speed 45", "verbatim"), ledger2, sources, assets, tmp_path)
    assert any(i.code == "TRANSFORM_MISMATCH" for i in lied.issues)

    # Rendering a claim with no spans -> RENDERING_UNBOUND error at publish.
    unbound = _run(deck_with("An unsupported statement.", None, claim_id="public-claim"), ledger2, sources, assets, tmp_path, publish=True)
    assert any(i.code == "RENDERING_UNBOUND" and i.severity == "error" for i in unbound.issues)


def test_decision_memory_rebuild(tmp_path: Path) -> None:
    import yaml as _yaml

    from pitchdeck.models import SourceManifest

    source_path = FIXTURE / "source_manifest.yaml"
    src = load_yaml(source_path, SourceManifest)
    out = tmp_path / "bundle"
    plan_bundle(src, source_manifest_path=source_path, output_dir=out, max_slides=10)

    # Human approves one claim (with provenance) between plans.
    ledger = _yaml.safe_load((out / "claim_ledger.yaml").read_text())
    target = next(c for c in ledger["claims"] if c["status"] == "candidate")
    target["status"] = "approved"
    target["approval"] = {"approved_by": "human", "approved_at": "2026-08-06"}
    (out / "claim_ledger.yaml").write_text(_yaml.safe_dump(ledger, sort_keys=False))

    # Re-plan into the same bundle: the decision must carry.
    receipt = plan_bundle(src, source_manifest_path=source_path, output_dir=out, max_slides=10)
    after = _yaml.safe_load((out / "claim_ledger.yaml").read_text())
    carried = next(c for c in after["claims"] if c["id"] == target["id"])
    assert carried["status"] == "approved"
    assert carried["approval"]["approved_by"] == "human"
    assert any("decision memory" in g for g in receipt.gaps)

    # Changed claim text must NOT inherit the approval.
    ledger2 = _yaml.safe_load((out / "claim_ledger.yaml").read_text())
    for c in ledger2["claims"]:
        if c["id"] == target["id"]:
            c["text"] = c["text"] + " with a materially different ending"
    (out / "claim_ledger.yaml").write_text(_yaml.safe_dump(ledger2, sort_keys=False))
    plan_bundle(src, source_manifest_path=source_path, output_dir=out, max_slides=10)
    final = _yaml.safe_load((out / "claim_ledger.yaml").read_text())
    reproposed = next(c for c in final["claims"] if c["id"] == target["id"])
    assert reproposed["status"] == "candidate"
    assert not reproposed.get("approval")


def test_living_deck_drift_and_versioning(tmp_path: Path) -> None:
    import json as _json

    from pitchdeck.drift import check_drift, pin_version, snapshot_sources
    from pitchdeck.models import SourceManifest

    source_path = FIXTURE / "source_manifest.yaml"
    src = load_yaml(source_path, SourceManifest)
    out = tmp_path / "bundle"
    plan_bundle(src, source_manifest_path=source_path, output_dir=out, max_slides=8)

    deck = load_yaml(out / "deck.public.yaml", DeckManifest)
    ledger = load_yaml(out / "claim_ledger.yaml", ClaimLedger)
    resolved = load_yaml(out / "source_manifest.resolved.yaml", SourceManifest)

    # No-op: fresh snapshot reports clean.
    report = check_drift(out, deck, ledger, resolved, source_path.parent)
    assert report["snapshot"] and report["no_op"]

    # Edit a source -> drift names it and maps affected claims; publish blocks.
    target = Path(resolved.sources[0].path)
    original = target.read_text()
    try:
        target.write_text(original + "\nA new paragraph that changes the source hash.\n")
        drifted = check_drift(out, deck, ledger, resolved, source_path.parent)
        assert resolved.sources[0].id in drifted["changed"] and not drifted["no_op"]
        assert drifted["affected_claims"], "changed source must map to claims"
        publish = validate_bundle(
            deck, ledger, resolved, load_yaml(out / "asset_manifest.yaml", AssetManifest),
            source_manifest_dir=source_path.parent, asset_manifest_dir=out,
            require_approved_claims=True,
        )
        assert any(i.code == "SOURCE_DRIFT" and i.severity == "error" for i in publish.issues)
        # Refresh snapshot -> clean again (the repair path).
        snapshot_sources(out, resolved, source_path.parent)
        assert check_drift(out, deck, ledger, resolved, source_path.parent)["no_op"]
    finally:
        target.write_text(original)
    snapshot_sources(out, resolved, source_path.parent)

    # Version pinning writes the hash set + revision beside the artifact.
    artifact = tmp_path / "deck.pptx"
    artifact.write_bytes(b"PK\x03\x04fake")
    version_path = pin_version(artifact, out, deck, 7)
    version = _json.loads(version_path.read_text())
    assert version["bundle_revision"] == 7 and version["source_sha256"]


def test_generated_pixels_never_claim_bearing(tmp_path: Path) -> None:
    from pitchdeck.models import AssetSpec, AssetKind, AssetStatus

    sources, ledger, assets = _base_models(tmp_path)
    generated = AssetSpec(
        id="gen-hero", kind=AssetKind.ILLUSTRATION, visibility=Visibility.PUBLIC,
        alt_text="abstract hero", status=AssetStatus.PLANNED,
        generation_brief="Illustration for slide, no text",
    )
    assets2 = assets.model_copy(update={"assets": [*assets.assets, generated]})
    # Generated asset on a claim-bearing visual type -> blocked.
    slide = _slide(visual=VisualSpec(type="native_diagram", items=["a", "b"], asset_id="gen-hero"))
    report = _run(_deck(slide), ledger, sources, assets2, tmp_path)
    assert any(i.code == "GENERATED_ASSET_CLAIM_SURFACE" for i in report.issues)
    # Same asset as a decorative image visual -> no gate hit.
    ok = _run(_deck(_slide(visual=VisualSpec(type="image", asset_id="gen-hero"))), ledger, sources, assets2, tmp_path)
    assert not any(i.code == "GENERATED_ASSET_CLAIM_SURFACE" for i in ok.issues)


def test_variation_plan_compiles_from_theme(tmp_path: Path, planned: Path) -> None:
    import json as _json

    from pitchdeck.image_variations import emit_variation_plan, run_variations

    deck = load_yaml(planned / "deck.public.yaml", DeckManifest)
    sid = sorted(deck.slides, key=lambda s: s.order)[1].id
    plan_path = emit_variation_plan(deck, sid, tmp_path / "vars", count=3)
    plan = _json.loads(plan_path.read_text())
    assert len(plan["variants"]) == 3
    assert deck.deck.theme_tokens.accent in plan["brief"]
    assert "MUST NOT contain any text" in plan["brief"]
    assert plan["tau_dag"]["topology"] == "concurrent" and len(plan["tau_dag"]["nodes"]) == 3
    # Without a key, live execution refuses honestly instead of fabricating.
    import os
    if not os.getenv("OPENAI_API_KEY"):
        result = run_variations(plan_path, tmp_path / "vars")
        assert result["status"] == "NEEDS_ATTENTION" and "OPENAI_API_KEY" in result["reason"]


def test_changeset_tokens_and_mcp(planned: Path, tmp_path: Path) -> None:
    import ast

    from pitchdeck.change_set import (
        DeckStructureOp,
        EditProposal,
        SetSlideField,
        apply_proposal,
        mint_confirmation_token,
        simulate_proposal,
    )
    from pitchdeck.mcp_server import handle_request
    from pitchdeck.revisions import current_revision

    deck = load_yaml(planned / "deck.public.yaml", DeckManifest)
    sid = sorted(deck.slides, key=lambda s: s.order)[1].id
    rev = current_revision(planned)

    # Cosmetic proposal: simulate then apply without a token.
    cosmetic = EditProposal(
        base_revision=rev,
        ops=[SetSlideField(slide_id=sid, field="footer", value="proposal footer")],
        rationale="cosmetic footer", idempotency_key="idem-cosmetic-1",
    )
    assert simulate_proposal(planned, cosmetic)["would_pass"]
    assert apply_proposal(planned, tmp_path / "ui", cosmetic)["applied"]

    # Governance proposal (delete) requires a token.
    rev2 = current_revision(planned)
    governance = EditProposal(
        base_revision=rev2,
        ops=[DeckStructureOp(deck_op="delete", slide_id=sid)],
        rationale="drop slide", idempotency_key="idem-gov-1",
    )
    with pytest.raises(PermissionError, match="confirmation token"):
        apply_proposal(planned, tmp_path / "ui", governance)

    # Cross-proposal token rejected; correct token works once; replay rejected.
    other = governance.model_copy(update={"idempotency_key": "idem-gov-2"})
    wrong = mint_confirmation_token(planned, other)
    with pytest.raises(PermissionError, match="different proposal"):
        apply_proposal(planned, tmp_path / "ui", governance, token=wrong)
    token = mint_confirmation_token(planned, governance)
    assert apply_proposal(planned, tmp_path / "ui", governance, token=token)["governance"]
    restore = EditProposal(
        base_revision=current_revision(planned),
        ops=[DeckStructureOp(deck_op="delete", slide_id=deck.slides[0].id)],
        rationale="x", idempotency_key="idem-gov-3",
    )
    with pytest.raises(PermissionError, match="unknown or already used"):
        apply_proposal(planned, tmp_path / "ui", restore, token=token)

    # Stale revision refuses.
    stale = EditProposal(
        base_revision=rev,  # long since advanced
        ops=[SetSlideField(slide_id="03-thesis", field="footer", value="x")],
        rationale="stale", idempotency_key="idem-stale-1",
    )
    result = simulate_proposal(planned, stale)  # simulate ignores CAS (dry)
    if result["would_pass"]:
        with pytest.raises(ValueError, match="revision"):
            apply_proposal(planned, tmp_path / "ui", stale)

    # MCP adapter: history works, token minting is NOT exposed, imports are clean.
    history = handle_request({"tool": "pitchdeck_history", "arguments": {"bundle_dir": str(planned)}})
    assert "revision" in history
    unknown = handle_request({"tool": "pitchdeck_mint_token", "arguments": {"bundle_dir": str(planned)}})
    assert "unknown tool" in unknown["error"]
    tree = ast.parse((Path(__file__).resolve().parents[1] / "src" / "pitchdeck" / "mcp_server.py").read_text())
    imported = {
        node.module for node in ast.walk(tree) if isinstance(node, ast.ImportFrom) and node.module
    }
    assert "pitchdeck.change_set" not in imported  # relative imports only
    for mod in imported:
        assert mod in {"__future__", "change_set", "revisions", "pathlib"} or not mod.startswith("pitchdeck"), mod
    mint_exposed = any(
        isinstance(n, ast.Name) and n.id == "mint_confirmation_token" for n in ast.walk(tree)
    )
    assert not mint_exposed, "MCP module must not mint confirmation tokens"
